export const meta = {
  name: 'pr-split-8362',
  description: 'Split wp-rocket PR #8362 into 7 focused sub-PRs, one per logical area',
  phases: [
    { title: 'Analysis', detail: 'Read the full diff and produce a section→file→changes map' },
    { title: 'Sub-PRs', detail: 'Create 7 branches and draft PRs in parallel (worktree isolation)' },
  ],
}

const REPO = '/Users/gaelrobin/Desktop/Work/wp-rocket'
const PR_BRANCH = 'origin/chore/ai-orchestration-improvements'
const BASE = 'develop'
const GH_REPO = 'wp-media/wp-rocket'

// ── Phase 1: Analysis ─────────────────────────────────────────────────────────
phase('Analysis')

const analysis = await agent(`
You are the Analysis Agent for a PR split operation.

Repository: ${REPO}
PR branch: ${PR_BRANCH}
Base: ${BASE}

Your job: produce a JSON plan that maps each of the 7 sub-PRs to:
- The exact files it owns
- A 2-3 sentence description of what changes to apply from the PR diff

The 7 sections are:
1. orchestrator — Changes to skills/orchestrator/SKILL.md (sequential flag, mandatory gates, pipeline stop fix) and skills/issue-workflow/SKILL.md + all scripts/refs inside issue-workflow/ (GitKraken removal, issue-workflow improvements)
2. agent-metadata — ONLY frontmatter additions (model:, maxTurns:, color:) to ALL agent .md files. No content changes, just the YAML frontmatter at the top of each agent file.
3. grooming — Changes to agents/grooming-agent.md (complexity_signal input, PR splitting plan for L/XL, effort_used/pr_splitting_plan output fields)
4. qa-e2e — Changes to agents/qa-engineer.md (UI keyword triggers for Strategy B, step renumbering), agents/e2e-qa-tester.md (Playwright spec source capture), skills/e2e/SKILL.md (anti-rationalization table)
5. dod-challenger — Changes to skills/dod/SKILL.md (anti-rationalization table, Check 2 strengthening, PHPCS guidance, Check 6, Layer 2 result file) and agents/challenger.md (Hyrum's Law angle, frontmatter)
6. impl-agents — Changes to agents/backend-agent.md, agents/frontend-agent.md, agents/lead-reviewer.md (result file contracts, event emission for backend/frontend, cross-file impact analysis for lead-reviewer)
7. release-agents-md — Changes to agents/release-agent.md (PR-issue link, label/assignee robustness, shell quoting fix) and AGENTS.md (5 operating principles)

Steps:
1. Run: git -C "${REPO}" diff ${BASE}...${PR_BRANCH} --name-only
2. For each of these key files, get the diff:
   - .aiassistant/agents/backend-agent.md
   - .aiassistant/agents/grooming-agent.md
   - .aiassistant/agents/qa-engineer.md
   - .aiassistant/skills/orchestrator/SKILL.md
   - .aiassistant/skills/dod/SKILL.md
   Run: git -C "${REPO}" diff ${BASE}...${PR_BRANCH} -- <file>
3. Based on what you see, write a detailed plan per section: which files it needs and exactly what changes to apply (quote the relevant +lines from the diff).

Return a JSON object:
{
  "sections": [
    {
      "id": "orchestrator",
      "branch": "chore/ai-split-orchestrator",
      "pr_title": "chore(ai): orchestrator — sequential mode, mandatory gates, issue-workflow cleanup",
      "pr_body": "...",
      "files": [".aiassistant/skills/orchestrator/SKILL.md", "..."],
      "instructions": "Detailed description of what changes to apply to each file"
    },
    ... (7 total)
  ]
}
`, {label: 'analysis', schema: {
  type: 'object',
  properties: {
    sections: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          branch: { type: 'string' },
          pr_title: { type: 'string' },
          pr_body: { type: 'string' },
          files: { type: 'array', items: { type: 'string' } },
          instructions: { type: 'string' }
        },
        required: ['id', 'branch', 'pr_title', 'pr_body', 'files', 'instructions']
      }
    }
  },
  required: ['sections']
}})

log('Analysis complete — ' + analysis.sections.length + ' sections mapped')
analysis.sections.forEach(s => log('  ' + s.id + ': ' + s.files.length + ' files → ' + s.branch))

// ── Phase 2: Sub-PRs (parallel, each in an isolated worktree) ─────────────────
phase('Sub-PRs')

const results = await parallel(analysis.sections.map(section => () =>
  agent(`
You are a Sub-PR Agent. Your job: create a focused branch and draft PR for ONE section of a large PR split.

Repository: ${REPO}
PR source branch (has all the changes): ${PR_BRANCH}
Base branch: ${BASE}
GitHub repo: ${GH_REPO}

YOUR SECTION: ${section.id}
Branch to create: ${section.branch}
PR title: ${section.pr_title}
Files you own: ${JSON.stringify(section.files)}
What to apply: ${section.instructions}

Steps:
1. Check out a fresh worktree from ${BASE}:
   git -C "${REPO}" worktree add /tmp/wt-${section.id} ${BASE}
   (if it already exists, run: git -C "${REPO}" worktree remove /tmp/wt-${section.id} --force first)

2. Create the branch:
   git -C /tmp/wt-${section.id} checkout -b ${section.branch}

3. For each file in your files list:
   a. Get the file content from the PR branch:
      git -C "${REPO}" show ${PR_BRANCH}:<file_path>
   b. Write that content to the worktree:
      Write it to /tmp/wt-${section.id}/<file_path> (create parent dirs if needed)

   IMPORTANT — for "agent-metadata" section only: do NOT copy full file content. Instead:
   - Read current file from develop: git -C "${REPO}" show ${BASE}:<file_path>
   - Read PR version: git -C "${REPO}" show ${PR_BRANCH}:<file_path>
   - Apply ONLY the frontmatter changes (model:, maxTurns:, color: lines) to the develop version
   - Write the result

4. Stage and commit:
   git -C /tmp/wt-${section.id} add ${section.files.map(f => f).join(' ')}
   git -C /tmp/wt-${section.id} commit -m "${section.pr_title}"

5. Push:
   git -C /tmp/wt-${section.id} push origin ${section.branch}

6. Create draft PR:
   gh pr create --repo ${GH_REPO} --base ${BASE} --head ${section.branch} --draft --title "${section.pr_title}" --body "${section.pr_body.replace(/"/g, '\\"')}"

7. Clean up worktree:
   git -C "${REPO}" worktree remove /tmp/wt-${section.id} --force

Report: PR URL created, files committed, any issues encountered.
  `, {label: section.id, phase: 'Sub-PRs'})
))

const created = results.filter(Boolean)
log('Done — ' + created.length + '/' + analysis.sections.length + ' sub-PRs created')

return { sections: analysis.sections.map((s, i) => ({ id: s.id, branch: s.branch, result: results[i] })) }
